type Session = { user?: { email?: string; username?: string | null } } | null;

/** Only accounts generated by createAccount can receive fixture data. */
export function assertSyntheticSession(session: Session, expectedEmail?: string) {
	const user = session?.user;
	if (
		!user?.username?.startsWith("e2e_") ||
		user.email !== `${user.username}@example.test` ||
		(expectedEmail !== undefined && user.email !== expectedEmail)
	) {
		throw new Error("E2E fixtures require their own disposable account. Refusing to use an owner or demo session.");
	}
}
